insert into public.ce_course2_resources(id,data) values
('course2_module4_pdf','{"base64": "", "sha256": "0e8cbf485fabed76af9ffc253cfa00db76461a7f0731cb0c1c409de70cccc15d", "filename": "CE_HALO_Course2_Module04_Von_Willebrand_Learner_FINAL.pdf", "mime_type": "application/pdf"}'::jsonb),
('course2_module4_questions','[{"module_id": "course_2_module_4", "question_id": "course_2_module_4_q01", "question_number": 1, "stem": "A 24-year-old woman is scheduled for elective septoplasty. She reports lifelong easy bruising, epistaxis 4–5 times per year requiring cautery on two occasions, and heavy menses. Her PT and aPTT are normal, platelet count is 245,000. Which is the most appropriate next step?", "choice_a": "Order a validated bleeding-assessment tool (ISTH-BAT), VWF antigen, VWF activity, and FVIII activity before proceeding.", "choice_b": "Give empiric DDAVP 0.3 mcg/kg IV at induction to cover possible undiagnosed VWD.", "choice_c": "Cancel the case pending genetic testing for VWD.", "choice_d": "Proceed to surgery as scheduled — normal PT/aPTT excludes a clinically significant bleeding disorder.", "correct_choice": "a", "rationale": "Normal PT and aPTT do not exclude VWD. Per the ASH 2021 diagnosis guideline, a patient with a positive bleeding history and low pretest probability should have a validated bleeding assessment (ISTH-BAT ≥6 for adult female is positive) plus VWF antigen, VWF activity, and FVIII activity. Empiric DDAVP is not appropriate without documented response and could be harmful in Type 2B. Genetic testing is not the first-line diagnostic step.", "hint": {"mode": "eliminate_two_wrong_answers", "eliminate_choices": ["b", "c"], "remaining_choices": ["a", "d"]}, "learning_objective_ids": [], "source_ids": [], "source_urls": [], "source_provenance": "provider_reviewed_submitted_content"}, {"module_id": "course_2_module_4", "question_id": "course_2_module_4_q02", "question_number": 2, "stem": "Which VWD subtype is characterized by a gain-of-function VWF mutation that binds platelets excessively, causing loss of high-molecular-weight multimers and intermittent thrombocytopenia?", "choice_a": "Type 2A", "choice_b": "Type 2B", "choice_c": "Type 1", "choice_d": "Type 2N", "correct_choice": "b", "rationale": "Type 2B is the gain-of-function VWF variant with increased platelet GPIb binding, which consumes both HMW multimers and platelets. This is the subtype in which empiric DDAVP is generally contraindicated because DDAVP-induced VWF release can worsen platelet aggregation and thrombocytopenia. Type 2A also has HMW multimer loss but by a different mechanism and without thrombocytopenia.", "hint": {"mode": "eliminate_two_wrong_answers", "eliminate_choices": ["a", "c"], "remaining_choices": ["b", "d"]}, "learning_objective_ids": [], "source_ids": [], "source_urls": [], "source_provenance": "provider_reviewed_submitted_content"}, {"module_id": "course_2_module_4", "question_id": "course_2_module_4_q03", "question_number": 3, "stem": "A patient with known Type 3 VWD is scheduled for elective cholecystectomy. What is the most appropriate preoperative hemostatic strategy?", "choice_a": "Fresh frozen plasma 15 mL/kg preoperatively.", "choice_b": "Tranexamic acid 1 g IV alone.", "choice_c": "Plasma-derived VWF/FVIII concentrate 40–60 IU/kg IV pre-incision with scheduled redosing and factor monitoring.", "choice_d": "DDAVP 0.3 mcg/kg IV 30 minutes before incision.", "correct_choice": "c", "rationale": "Type 3 VWD has near-complete absence of VWF; DDAVP is not effective because there are no endogenous stores to release. Plasma-derived VWF/FVIII concentrate (Humate-P, wilate, or Alphanate — though Alphanate is not indicated for major surgery in Type 3) is the standard. Vonvendi paired with recombinant FVIII is an alternative. TXA and FFP alone are inadequate for Type 3 major surgery.", "hint": {"mode": "eliminate_two_wrong_answers", "eliminate_choices": ["a", "b"], "remaining_choices": ["c", "d"]}, "learning_objective_ids": [], "source_ids": [], "source_urls": [], "source_provenance": "provider_reviewed_submitted_content"}, {"module_id": "course_2_module_4", "question_id": "course_2_module_4_q04", "question_number": 4, "stem": "Per the ASH 2021 guideline, what VWF activity and FVIII targets should be maintained after major surgery in a patient with VWD, and for how long?", "choice_a": "FVIII ≥50 IU/dL only, VWF not monitored postoperatively.", "choice_b": "VWF and FVIII ≥100 IU/dL for 14 days.", "choice_c": "VWF ≥30 IU/dL for 24 hours.", "choice_d": "VWF and FVIII ≥50 IU/dL for at least 3 consecutive days.", "correct_choice": "d", "rationale": "The ASH 2021 guideline, based on the Brignardello-Petersen 2022 systematic review, recommends maintaining VWF activity and FVIII activity ≥0.50 IU/mL (50 IU/dL) for at least 3 consecutive days after major surgery. Many programs continue for 7–14 days depending on procedure and bleeding, but the evidence-based minimum is 3 days at 50 IU/dL.", "hint": {"mode": "eliminate_two_wrong_answers", "eliminate_choices": ["a", "b"], "remaining_choices": ["c", "d"]}, "learning_objective_ids": [], "source_ids": [], "source_urls": [], "source_provenance": "provider_reviewed_submitted_content"}, {"module_id": "course_2_module_4", "question_id": "course_2_module_4_q05", "question_number": 5, "stem": "A 68-year-old woman with severe aortic stenosis (mean gradient 55 mmHg) has had three episodes of GI bleeding from small-bowel angiodysplasia in the past year. Preoperative workup for TAVR shows VWF antigen 90 IU/dL, VWF activity 40 IU/dL, activity/antigen ratio 0.44, HMW multimer loss on multimer analysis. What is the most likely diagnosis?", "choice_a": "Heyde syndrome — severe AS with acquired VWS from HMW multimer shearing", "choice_b": "Late-onset Type 1 VWD", "choice_c": "Chronic disseminated intravascular coagulation", "choice_d": "Type 2N VWD", "correct_choice": "a", "rationale": "Heyde syndrome is the clinical triad of severe aortic stenosis, GI bleeding from small-bowel angiodysplasia, and acquired VWS from mechanical shearing of HMW multimers across the stenotic valve. The activity/antigen ratio <0.7 and HMW multimer loss are the diagnostic laboratory pattern. TAVR (or surgical AVR) reliably reverses the acquired VWS within 24–72 hours as valvular shear normalizes.", "hint": {"mode": "eliminate_two_wrong_answers", "eliminate_choices": ["b", "c"], "remaining_choices": ["a", "d"]}, "learning_objective_ids": [], "source_ids": [], "source_urls": [], "source_provenance": "provider_reviewed_submitted_content"}, {"module_id": "course_2_module_4", "question_id": "course_2_module_4_q06", "question_number": 6, "stem": "A DDAVP-responsive Type 1 VWD patient receives DDAVP 0.3 mcg/kg IV for a dental extraction. Which perioperative management principle is most important?", "choice_a": "Give supplemental hypotonic fluid to prevent hypernatremia.", "choice_b": "Fluid-restrict to approximately 1 L/day, avoid hypotonic fluids, and monitor serum sodium.", "choice_c": "Combine with therapeutic-dose enoxaparin to prevent VTE.", "choice_d": "Give a second identical DDAVP dose in 4 hours to prolong the effect.", "correct_choice": "b", "rationale": "DDAVP is antidiuretic and causes free-water retention; the specific hazard is symptomatic hyponatremia, particularly in children, older adults, and those with cardiovascular disease. Fluid restriction to ~1 L/day, avoidance of hypotonic fluids, and sodium monitoring are the standard precautions. Tachyphylaxis limits the benefit of a repeat dose within 24 hours. Anticoagulation is not indicated.", "hint": {"mode": "eliminate_two_wrong_answers", "eliminate_choices": ["a", "c"], "remaining_choices": ["b", "d"]}, "learning_objective_ids": [], "source_ids": [], "source_urls": [], "source_provenance": "provider_reviewed_submitted_content"}, {"module_id": "course_2_module_4", "question_id": "course_2_module_4_q07", "question_number": 7, "stem": "Which of the following VWF replacement products does NOT contain factor VIII?", "choice_a": "Humate-P", "choice_b": "Alphanate", "choice_c": "Vonvendi (vonicog alfa, recombinant VWF)", "choice_d": "wilate", "correct_choice": "c", "rationale": "Vonvendi is a recombinant human VWF product and does not contain FVIII. In elective surgery it is typically given 12–24 h preoperatively to allow endogenous FVIII to rise once VWF becomes available to stabilize it. In urgent surgery with low baseline FVIII, Vonvendi must be paired with a recombinant FVIII product to achieve immediate correction of both. Humate-P, wilate, and Alphanate are all plasma-derived and contain both VWF and FVIII.", "hint": {"mode": "eliminate_two_wrong_answers", "eliminate_choices": ["a", "b"], "remaining_choices": ["c", "d"]}, "learning_objective_ids": [], "source_ids": [], "source_urls": [], "source_provenance": "provider_reviewed_submitted_content"}, {"module_id": "course_2_module_4", "question_id": "course_2_module_4_q08", "question_number": 8, "stem": "Per ASH 2021, what is the recommended oral tranexamic acid regimen for a patient with mild VWD undergoing dental extraction?", "choice_a": "5 g PO loading dose once, no maintenance.", "choice_b": "500 mg PO once at the time of extraction only.", "choice_c": "1 g PO daily for 3 days.", "choice_d": "25 mg/kg (typically 1,000–1,300 mg) PO three times daily for 5–7 days.", "correct_choice": "d", "rationale": "ASH 2021 recommends oral TXA at 25 mg/kg (typically 1,000–1,300 mg) three times daily for 5–7 days for dental extractions and similar mucosal procedures in patients with VWD. This antifibrinolytic coverage substantially reduces delayed mucosal rebleeding as the primary clot begins to dissolve.", "hint": {"mode": "eliminate_two_wrong_answers", "eliminate_choices": ["a", "b"], "remaining_choices": ["c", "d"]}, "learning_objective_ids": [], "source_ids": [], "source_urls": [], "source_provenance": "provider_reviewed_submitted_content"}, {"module_id": "course_2_module_4", "question_id": "course_2_module_4_q09", "question_number": 9, "stem": "A parturient with well-controlled Type 1 VWD (VWF activity 115 IU/dL, FVIII 128 IU/dL at admission; institutional target ≥100 IU/dL for neuraxial) receives a labor epidural without complication. Four hours postpartum she requests removal. What is the most important consideration before removing the catheter?", "choice_a": "Verify current VWF activity meets institutional threshold (≥100 IU/dL) before removal.", "choice_b": "Remove the catheter immediately — postpartum removal timing does not depend on factor levels.", "choice_c": "Give an additional DDAVP dose immediately before removal.", "choice_d": "Wait 24 hours regardless of factor levels.", "correct_choice": "a", "rationale": "Factor levels must be at institutional threshold BOTH at the time of neuraxial placement AND at the time of catheter removal. Postpartum VWF and FVIII can fall rapidly, and catheter removal below target is a described mechanism of delayed epidural hematoma. Verifying the current level before removal is the appropriate standard.", "hint": {"mode": "eliminate_two_wrong_answers", "eliminate_choices": ["b", "c"], "remaining_choices": ["a", "d"]}, "learning_objective_ids": [], "source_ids": [], "source_urls": [], "source_provenance": "provider_reviewed_submitted_content"}, {"module_id": "course_2_module_4", "question_id": "course_2_module_4_q10", "question_number": 10, "stem": "Which multimodal analgesic strategy is most appropriate in a Type 1 VWD patient after major abdominal surgery?", "choice_a": "Aspirin 650 mg PO every 4 hours plus acetaminophen.", "choice_b": "Scheduled acetaminophen 1 g PO q6h, IV lidocaine infusion 1 mg/kg/h, opioid PCA, avoid NSAIDs.", "choice_c": "Ibuprofen 800 mg PO every 8 hours as primary analgesic.", "choice_d": "Scheduled ketorolac 30 mg IV every 6 hours for 48 hours plus opioid PRN.", "correct_choice": "b", "rationale": "NSAIDs (ketorolac, ibuprofen, naproxen, diclofenac) reversibly inhibit platelet COX-1 for 24–72 hours, and this effect is additive to the VWD defect; they should be avoided unless hematology specifically agrees. Aspirin is irreversibly platelet-inhibiting and also avoided. Acetaminophen, IV lidocaine infusion, opioid PCA, low-dose ketamine, and local anesthetic techniques are all appropriate opioid-sparing alternatives.", "hint": {"mode": "eliminate_two_wrong_answers", "eliminate_choices": ["a", "c"], "remaining_choices": ["b", "d"]}, "learning_objective_ids": [], "source_ids": [], "source_urls": [], "source_provenance": "provider_reviewed_submitted_content"}, {"module_id": "course_2_module_4", "question_id": "course_2_module_4_q11", "question_number": 11, "stem": "A 55-year-old man on chronic left ventricular assist device (HeartMate 3) support presents with recurrent epistaxis. Which finding is expected?", "choice_a": "Prolonged PT due to factor VII inhibition.", "choice_b": "Isolated thrombocytopenia with normal VWF and FVIII.", "choice_c": "Loss of HMW VWF multimers on multimer analysis, consistent with LVAD-induced acquired VWS.", "choice_d": "Elevated VWF activity from LVAD-induced endothelial activation.", "correct_choice": "c", "rationale": "Continuous-flow LVADs (HeartMate II, HeartMate 3) produce high shear stress that mechanically cleaves the largest VWF multimers, causing acquired VWS with selective HMW multimer loss. This is a well-described contributor to mucosal and GI bleeding in LVAD patients. The activity/antigen ratio is characteristically reduced.", "hint": {"mode": "eliminate_two_wrong_answers", "eliminate_choices": ["a", "b"], "remaining_choices": ["c", "d"]}, "learning_objective_ids": [], "source_ids": [], "source_urls": [], "source_provenance": "provider_reviewed_submitted_content"}, {"module_id": "course_2_module_4", "question_id": "course_2_module_4_q12", "question_number": 12, "stem": "Which pattern of laboratory findings is most consistent with Type 2N VWD?", "choice_a": "VWF antigen <10 IU/dL, VWF activity <10 IU/dL, FVIII 6 IU/dL.", "choice_b": "VWF antigen 30 IU/dL, VWF activity 28 IU/dL (ratio 0.93), FVIII 40 IU/dL, normal multimers.", "choice_c": "VWF antigen 90 IU/dL, VWF activity 35 IU/dL (ratio 0.39), FVIII 85 IU/dL, HMW multimer loss.", "choice_d": "VWF antigen 80 IU/dL, VWF activity 78 IU/dL (ratio 0.98), FVIII 22 IU/dL, abnormal VWF:FVIII binding.", "correct_choice": "d", "rationale": "Type 2N (\"Normandy\") is characterized by defective VWF-FVIII binding, producing normal or near-normal VWF antigen and activity but disproportionately low FVIII. The VWF:FVIII binding assay is abnormal. Choice A is Type 3, choice C is Type 2A pattern (HMW loss with reduced activity/antigen ratio), and choice D is Type 1.", "hint": {"mode": "eliminate_two_wrong_answers", "eliminate_choices": ["a", "b"], "remaining_choices": ["c", "d"]}, "learning_objective_ids": [], "source_ids": [], "source_urls": [], "source_provenance": "provider_reviewed_submitted_content"}, {"module_id": "course_2_module_4", "question_id": "course_2_module_4_q13", "question_number": 13, "stem": "A patient with Type 2B VWD undergoing elective cholecystectomy has preoperative platelet count 95,000/μL and VWF activity 25 IU/dL. Which preoperative hemostatic strategy is most appropriate?", "choice_a": "Plasma-derived VWF/FVIII concentrate at 40 IU/kg with hematology guidance; avoid empiric DDAVP.", "choice_b": "Tranexamic acid IV as monotherapy.", "choice_c": "DDAVP 0.3 mcg/kg IV to raise both VWF and FVIII.", "choice_d": "Platelet transfusion to reach 150,000 followed by DDAVP.", "correct_choice": "a", "rationale": "DDAVP is generally contraindicated in Type 2B because DDAVP-induced release of the abnormal gain-of-function VWF can worsen platelet aggregation and thrombocytopenia. Plasma-derived VWF concentrate is the recommended first-line hemostatic therapy, with adjunctive TXA for mucosal bleeding risk. TXA alone is inadequate for a major abdominal case.", "hint": {"mode": "eliminate_two_wrong_answers", "eliminate_choices": ["b", "c"], "remaining_choices": ["a", "d"]}, "learning_objective_ids": [], "source_ids": [], "source_urls": [], "source_provenance": "provider_reviewed_submitted_content"}, {"module_id": "course_2_module_4", "question_id": "course_2_module_4_q14", "question_number": 14, "stem": "Per the ASH 2021 recommendation for neuraxial anesthesia in obstetric VWD patients, what factor activity range does the guideline support?", "choice_a": "≥200 IU/dL required regardless of clinical situation", "choice_b": "50–150 IU/dL (with many institutions targeting ≥100 IU/dL as a more conservative practical threshold)", "choice_c": "30–50 IU/dL", "choice_d": "10–30 IU/dL", "correct_choice": "b", "rationale": "The ASH 2021 conditional recommendation for neuraxial anesthesia in obstetric VWD is factor levels in the 50–150 IU/dL range, with acknowledgment of very low certainty of evidence and no established minimum threshold. Contemporary institutional practice (Sharpe et al., 2024) has trended toward ≥100 IU/dL as a more conservative practical target, particularly when recombinant VWF is used.", "hint": {"mode": "eliminate_two_wrong_answers", "eliminate_choices": ["a", "c"], "remaining_choices": ["b", "d"]}, "learning_objective_ids": [], "source_ids": [], "source_urls": [], "source_provenance": "provider_reviewed_submitted_content"}, {"module_id": "course_2_module_4", "question_id": "course_2_module_4_q15", "question_number": 15, "stem": "A 62-year-old man with Type 1 VWD has been receiving Humate-P 40 IU/kg IV q12h for postoperative hemostasis after knee arthroplasty. On postoperative day 3, his VWF activity is 88 IU/dL and FVIII is 320 IU/dL. What is the most appropriate action?", "choice_a": "Increase the dose to 60 IU/kg q12h because bleeding protection is inadequate.", "choice_b": "Continue current dosing to maintain hemostasis.", "choice_c": "Extend the dosing interval or reduce the dose to lower FVIII toward ≤250 IU/dL and reduce VTE risk.", "choice_d": "Discontinue mechanical VTE prophylaxis given the elevated FVIII.", "correct_choice": "c", "rationale": "Repeated dosing of plasma-derived VWF/FVIII concentrate can push trough FVIII above 250–300 IU/dL because endogenous FVIII production continues and adds to the exogenous supply. Elevated FVIII substantially increases venous thromboembolism risk, particularly after orthopedic surgery. Options include extending the dosing interval, reducing the dose, or switching to Vonvendi (no FVIII content). Mechanical VTE prophylaxis should be continued.", "hint": {"mode": "eliminate_two_wrong_answers", "eliminate_choices": ["a", "b"], "remaining_choices": ["c", "d"]}, "learning_objective_ids": [], "source_ids": [], "source_urls": [], "source_provenance": "provider_reviewed_submitted_content"}, {"module_id": "course_2_module_4", "question_id": "course_2_module_4_q16", "question_number": 16, "stem": "Which laboratory assay best distinguishes Type 2A from Type 2M VWD?", "choice_a": "VWF antigen", "choice_b": "FVIII activity", "choice_c": "PT / aPTT", "choice_d": "Multimer analysis", "correct_choice": "d", "rationale": "Type 2A shows loss of high-molecular-weight multimers on multimer analysis; Type 2M shows preserved multimers despite reduced platelet or collagen binding function. Both have activity/antigen ratios <0.7 (qualitative defects), so multimer analysis is the discriminating test. PT/aPTT are insensitive to VWD subtype.", "hint": {"mode": "eliminate_two_wrong_answers", "eliminate_choices": ["a", "b"], "remaining_choices": ["c", "d"]}, "learning_objective_ids": [], "source_ids": [], "source_urls": [], "source_provenance": "provider_reviewed_submitted_content"}, {"module_id": "course_2_module_4", "question_id": "course_2_module_4_q17", "question_number": 17, "stem": "A patient with type 1 VWD is scheduled for elective septoplasty. The hematology plan calls for DDAVP 0.3 mcg/kg IV 30 minutes preoperatively plus tranexamic acid 1 g IV at induction. Which additional postoperative order best reduces the risk of delayed mucosal bleeding?", "choice_a": "Oral tranexamic acid 25 mg/kg (approximately 1,300 mg) PO three times daily for 5–7 days.", "choice_b": "Ibuprofen 400 mg PO every 6 hours as needed.", "choice_c": "Aspirin 81 mg PO daily for 7 days.", "choice_d": "Warfarin 5 mg PO daily for 30 days.", "correct_choice": "a", "rationale": "Postoperative oral TXA at the ASH-recommended dose reduces delayed mucosal rebleeding, which typically occurs 24–72 hours postoperatively as the initial fibrin clot begins to dissolve and DDAVP effect wanes. Aspirin, NSAIDs, and warfarin all increase bleeding risk and are contraindicated.", "hint": {"mode": "eliminate_two_wrong_answers", "eliminate_choices": ["b", "c"], "remaining_choices": ["a", "d"]}, "learning_objective_ids": [], "source_ids": [], "source_urls": [], "source_provenance": "provider_reviewed_submitted_content"}, {"module_id": "course_2_module_4", "question_id": "course_2_module_4_q18", "question_number": 18, "stem": "A patient with Type 3 VWD receives Vonvendi 50 IU/kg IV for urgent appendectomy. Baseline FVIII is 8 IU/dL. What is the most important additional consideration?", "choice_a": "No FVIII correction is needed because VWF replacement alone is sufficient.", "choice_b": "Vonvendi does not contain FVIII; pair with recombinant FVIII to achieve immediate FVIII correction because endogenous FVIII rise takes 6–12 hours.", "choice_c": "Vonvendi will immediately raise FVIII to the therapeutic range within 30 minutes.", "choice_d": "Give tranexamic acid contraindication check because TXA cannot be used with Vonvendi.", "correct_choice": "b", "rationale": "Vonvendi is recombinant VWF only and does not contain FVIII. In elective surgery it can be given 12–24 h before incision to allow endogenous FVIII to rise. In urgent surgery with low baseline FVIII (as in Type 3), Vonvendi must be paired with recombinant FVIII to achieve immediate correction of both parameters. TXA is compatible with Vonvendi.", "hint": {"mode": "eliminate_two_wrong_answers", "eliminate_choices": ["a", "c"], "remaining_choices": ["b", "d"]}, "learning_objective_ids": [], "source_ids": [], "source_urls": [], "source_provenance": "provider_reviewed_submitted_content"}, {"module_id": "course_2_module_4", "question_id": "course_2_module_4_q19", "question_number": 19, "stem": "Which preoperative bleeding assessment score, using the ISTH Bleeding Assessment Tool (ISTH-BAT), should prompt further laboratory workup in an adult woman with a history suggestive of VWD?", "choice_a": "≥3", "choice_b": "≥10", "choice_c": "≥6", "choice_d": "≥2", "correct_choice": "c", "rationale": "Per the ASH 2021 diagnosis guideline, an ISTH-BAT score of ≥4 in an adult male, ≥6 in an adult female, or ≥3 in a child is considered positive and prompts targeted laboratory testing for VWD. The higher female threshold reflects menstruation as a common bleeding source that does not itself indicate a disorder.", "hint": {"mode": "eliminate_two_wrong_answers", "eliminate_choices": ["a", "b"], "remaining_choices": ["c", "d"]}, "learning_objective_ids": [], "source_ids": [], "source_urls": [], "source_provenance": "provider_reviewed_submitted_content"}, {"module_id": "course_2_module_4", "question_id": "course_2_module_4_q20", "question_number": 20, "stem": "During elective total knee arthroplasty in a patient with known Type 1 VWD (received DDAVP 0.3 mcg/kg IV 30 minutes before incision), the CRNA notices diffuse oozing at the surgical site and from the intravenous cannulation sites. What is the most appropriate immediate action?", "choice_a": "Deepen the anesthetic with volatile agent to lower blood pressure and reduce bleeding.", "choice_b": "Give a second DDAVP dose 4 hours after the first for additive VWF release.", "choice_c": "Give ketorolac 30 mg IV for analgesia and to reduce inflammation.", "choice_d": "Reassess temperature, pH, ionized calcium, and platelet count; confirm DDAVP was delivered on time; and consider VWF-containing concentrate plus IV tranexamic acid.", "correct_choice": "d", "rationale": "The unexpected-bleeding action bundle begins with reassessment of the physiologic contributors to coagulopathy (temperature, pH, calcium) and confirmation that planned hemostatic therapy was actually given at the intended time. Adding VWF-containing concentrate and IV TXA addresses the specific VWD defect. Repeat DDAVP within 24 hours yields little additional benefit (tachyphylaxis). NSAIDs are contraindicated. Lowering blood pressure alone does not address a hemostatic defect.", "hint": {"mode": "eliminate_two_wrong_answers", "eliminate_choices": ["a", "b"], "remaining_choices": ["c", "d"]}, "learning_objective_ids": [], "source_ids": [], "source_urls": [], "source_provenance": "provider_reviewed_submitted_content"}, {"module_id": "course_2_module_4", "question_id": "course_2_module_4_q21", "question_number": 21, "stem": "Which of the following is the most important element of the postoperative handoff for a patient with Type 3 VWD after major abdominal surgery?", "choice_a": "The subtype, product administered, next scheduled dose, laboratory monitoring plan, signs of concern, and hematology contact.", "choice_b": "The patient''s dietary preferences.", "choice_c": "The exact intraoperative volume of intravenous crystalloid.", "choice_d": "The specific brand of surgical drain used.", "correct_choice": "a", "rationale": "The CRNA handoff for a VWD patient after major surgery must specify the subtype, therapies administered (product, dose, timing), the next scheduled dose, laboratory monitoring intervals, signs of concern (delayed bleeding, hematuria, calf swelling for VTE), and hematology contact information. This continuity is essential to avoid missed doses and to recognize delayed bleeding or thrombosis promptly.", "hint": {"mode": "eliminate_two_wrong_answers", "eliminate_choices": ["b", "c"], "remaining_choices": ["a", "d"]}, "learning_objective_ids": [], "source_ids": [], "source_urls": [], "source_provenance": "provider_reviewed_submitted_content"}, {"module_id": "course_2_module_4", "question_id": "course_2_module_4_q22", "question_number": 22, "stem": "A term parturient with Type 3 VWD has been receiving wilate 40 IU/kg IV q12h beginning 24 hours before scheduled cesarean delivery, with a target VWF and FVIII ≥100 IU/dL for neuraxial placement. Just before spinal placement, the current VWF activity is 62 IU/dL and FVIII is 48 IU/dL. What is the most appropriate action?", "choice_a": "Cancel the case indefinitely.", "choice_b": "Give an additional wilate dose to reach institutional target ≥100 IU/dL before neuraxial placement, or convert to general anesthesia.", "choice_c": "Place the spinal anyway — 62 IU/dL is within the ASH guideline range.", "choice_d": "Give DDAVP 0.3 mcg/kg IV to boost endogenous VWF and proceed.", "correct_choice": "b", "rationale": "The institutional target of ≥100 IU/dL has not been met, and neuraxial placement below the planned threshold increases hematoma risk. Appropriate responses are to give an additional loading dose of wilate to reach target or to convert to general anesthesia. DDAVP is not effective in Type 3 (no endogenous stores). The case need not be cancelled — the obstetric indication remains.", "hint": {"mode": "eliminate_two_wrong_answers", "eliminate_choices": ["a", "c"], "remaining_choices": ["b", "d"]}, "learning_objective_ids": [], "source_ids": [], "source_urls": [], "source_provenance": "provider_reviewed_submitted_content"}, {"module_id": "course_2_module_4", "question_id": "course_2_module_4_q23", "question_number": 23, "stem": "Which of the following is a specific contraindication to systemic tranexamic acid?", "choice_a": "Postpartum hemorrhage prophylaxis.", "choice_b": "Menorrhagia in a patient with VWD.", "choice_c": "Upper urinary tract bleeding (risk of clot retention and obstruction) or active venous thromboembolic disease.", "choice_d": "Tonsillectomy in a patient with Type 1 VWD.", "correct_choice": "c", "rationale": "TXA is contraindicated in upper urinary tract bleeding because clot stabilization in the ureter or renal pelvis can cause obstructive uropathy, and in active thromboembolic disease because it opposes fibrinolysis. TXA is specifically recommended for menorrhagia, postpartum hemorrhage, and mucosal procedures such as tonsillectomy.", "hint": {"mode": "eliminate_two_wrong_answers", "eliminate_choices": ["a", "b"], "remaining_choices": ["c", "d"]}, "learning_objective_ids": [], "source_ids": [], "source_urls": [], "source_provenance": "provider_reviewed_submitted_content"}, {"module_id": "course_2_module_4", "question_id": "course_2_module_4_q24", "question_number": 24, "stem": "A patient with severe aortic stenosis and diagnosed Heyde syndrome (acquired VWS) is scheduled for TAVR. Which statement about postoperative acquired VWS is most accurate?", "choice_a": "Postoperative DDAVP must be given daily for 30 days to prevent recurrence.", "choice_b": "The acquired VWS is permanent and will require lifelong VWF replacement.", "choice_c": "The acquired VWS will worsen after TAVR because prosthetic materials increase shear stress.", "choice_d": "TAVR reliably reverses the acquired VWS within 24–72 hours as valvular shear stress normalizes and HMW multimers recover.", "correct_choice": "d", "rationale": "TAVR (and surgical AVR) reliably reverses Heyde-syndrome acquired VWS within 24–72 hours as the shear stress across the valve normalizes, allowing HMW multimers to recover. This is why preoperative VWF concentrate is often not required for elective TAVR in Heyde syndrome — the definitive treatment removes the underlying mechanism. GI angiodysplasia bleeding also typically resolves.", "hint": {"mode": "eliminate_two_wrong_answers", "eliminate_choices": ["a", "b"], "remaining_choices": ["c", "d"]}, "learning_objective_ids": [], "source_ids": [], "source_urls": [], "source_provenance": "provider_reviewed_submitted_content"}, {"module_id": "course_2_module_4", "question_id": "course_2_module_4_q25", "question_number": 25, "stem": "Which of the following situations most urgently warrants delaying elective surgery to obtain a hematology consultation and documented hemostatic plan?", "choice_a": "A patient with new-onset severe menorrhagia, ISTH-BAT score 8, mildly prolonged aPTT, and family history of postpartum hemorrhage, scheduled for hysterectomy in one week.", "choice_b": "A patient with no bleeding history and normal PT/aPTT.", "choice_c": "A patient with well-controlled hypertension scheduled for carpal tunnel release.", "choice_d": "A patient with known Type 1 VWD, prior successful DDAVP-covered dental extraction, scheduled for repeat dental extraction.", "correct_choice": "a", "rationale": "The presentation strongly suggests undiagnosed VWD (positive ISTH-BAT, prolonged aPTT that may reflect low FVIII, family history) and the planned operation is major with substantial mucosal bleeding risk. Proceeding without a documented VWF/FVIII workup and hematology plan risks major perioperative hemorrhage. The other scenarios do not require delay.", "hint": {"mode": "eliminate_two_wrong_answers", "eliminate_choices": ["b", "c"], "remaining_choices": ["a", "d"]}, "learning_objective_ids": [], "source_ids": [], "source_urls": [], "source_provenance": "provider_reviewed_submitted_content"}]'::jsonb)
